output.sparql:
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
SELECT DISTINCT ?language WHERE {
  ?language wdt:P31 wd:Q34770 ; wdt:P1447 ?percentage .
  FILTER(?percentage > 3.5)
}

